def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def value(row, key):
        item = row.get(key, "")
        return "" if item is None else str(item)

    def normalize_email(raw):
        raw = raw.strip()
        match = re.search(r"<([^<>]*)>", raw)
        if match:
            raw = match.group(1)
        email = raw.strip().lower()

        if email.count("@") != 1:
            return ""
        local, domain = email.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            email = f"{local}@{domain}"

        if (
            not local
            or not domain
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""
        return email

    def normalize_phone(raw):
        raw = raw.strip()
        match = re.search(r"x|ext|#", raw, flags=re.IGNORECASE)
        if match:
            raw = raw[:match.start()]
        digits = "".join(ch for ch in raw if ch.isdigit())
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(raw):
        zip_code = raw.strip()
        if "-" in zip_code:
            zip_code = zip_code.split("-", 1)[0]
        if len(zip_code) == 4 and zip_code.isdigit():
            zip_code = "0" + zip_code
        return zip_code if len(zip_code) == 5 and zip_code.isdigit() else ""

    def normalize_name(raw):
        name = raw.strip()
        if name.isupper() or name.islower():
            name = name.title()
        return name

    def parse_updated(raw):
        raw = raw.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(raw, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {raw!r}")

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(value(row, "email"))
        phone = normalize_phone(value(row, "phone"))
        if not email and not phone:
            continue

        updated = parse_updated(value(row, "updated"))
        first_name = normalize_name(value(row, "first_name"))
        last_name = normalize_name(value(row, "last_name"))
        source = value(row, "source").strip().lower()
        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", value(row, "tags"))
            if tag.strip()
        }
        opted_out = value(row, "opted_out").strip().lower() in {
            "y", "yes", "true", "1"
        }

        prepared.append({
            "index": index,
            "updated_dt": updated,
            "first_name": first_name,
            "last_name": last_name,
            "zip": normalize_zip(value(row, "zip")),
            "email": email,
            "phone": phone,
            "source": source,
            "tags": tags,
            "opted_out": opted_out,
        })

    # Union-find makes the matching transitive.
    parent = list(range(len(prepared)))

    def find(item):
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root != right_root:
            parent[right_root] = left_root

    email_owner = {}
    phone_name_owner = {}
    for i, person in enumerate(prepared):
        if person["email"]:
            if person["email"] in email_owner:
                union(i, email_owner[person["email"]])
            else:
                email_owner[person["email"]] = i

        last_name_key = person["last_name"].casefold()
        if person["phone"] and last_name_key:
            key = (person["phone"], last_name_key)
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, person in enumerate(prepared):
        groups.setdefault(find(i), []).append(person)

    def choose(group, field, require_valid=False):
        candidates = [
            person for person in group
            if person[field] and (not require_valid or person[field])
        ]
        if not candidates:
            return ""
        chosen = min(
            candidates,
            key=lambda person: (
                person["source"] != "manual",
                -person["updated_dt"].timestamp(),
                person["index"],
            ),
        )
        return chosen[field]

    output = []
    ordered_groups = sorted(groups.values(), key=lambda group: min(p["index"] for p in group))
    for group in ordered_groups:
        latest = max(person["updated_dt"] for person in group)
        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email", require_valid=True),
            "phone": choose(group, "phone", require_valid=True),
            "source": choose(group, "source"),
            "tags": ";".join(sorted(set().union(*(person["tags"] for person in group)))),
            "opted_out": "Y" if any(person["opted_out"] for person in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
